1	export type ProcessingState = "queued" | "processing" | "settled" | "rejected";
2	
3	export interface RecordState {
4	  refundId: string;
5	  processingState: ProcessingState;
6	}
7	
8	/** Refund settlement processing updates published to the operations dashboard. */
9	export function applyProcessingState(
10	  record: RecordState,
11	  state: ProcessingState,
12	  publish: (frame: object) => void,
13	): void {
14	  record.processingState = state;
15	  publish({
16	    resource: { id: record.refundId, processing_status: record.processingState },
17	    type: "refund_settlement",
18	    event: "status_changed",
19	  });
20	}
